<template>
  <ManagementPage title="预测管理">
    <template #title-extra><HelpIcon label="查看预测管理边界" content="配置导入只生成可编辑 draft 草稿；运行由服务端从已入库 active 能耗数据生成不可变快照。预测结果仅可筛选、查看和导出，不能人工导入、新建、编辑或删除。" /></template>
    <PageState v-if="!canManagePredictions" description="当前账号没有预测配置、预测运行或预测结果的查看权限。请联系管理员授予 prediction:config/view、prediction:run/view 或 prediction:result/view 权限；服务端仍会最终鉴权。" />

    <template v-else>
      <section v-if="canConfigView" class="module-section">
        <header class="module-heading"><div class="heading-with-help"><h2>预测配置草稿</h2><HelpIcon label="查看配置草稿说明" content="草稿可以新增、编辑、复制、归档和恢复。已归档草稿不可编辑或运行，须恢复或复制为新草稿。配置表格导入只创建 draft，不会运行预测或写入结果。" /></div></header>
        <ManagementToolbar :loading="configLoading" @search="applyConfigFilters" @reset="resetConfigFilters">
          <el-form-item label="状态"><el-select v-model="configDraftFilters.status" clearable placeholder="全部状态"><el-option label="草稿" value="draft" /><el-option label="启用" value="active" /><el-option label="已归档" value="archived" /></el-select></el-form-item>
          <el-form-item label="能源类型"><el-select v-model="configDraftFilters.energyTypeCode" clearable placeholder="全部能源类型"><el-option v-for="item in energyTypes" :key="item.code" :label="`${item.name}（${item.code}）`" :value="item.code" /></el-select></el-form-item>
          <el-form-item label="算法"><el-select v-model="configDraftFilters.algorithm" clearable placeholder="全部算法"><el-option label="移动平均" value="moving_average" /><el-option label="线性趋势" value="linear_trend" /></el-select></el-form-item>
          <el-form-item label="字符搜索"><el-input v-model.trim="configDraftFilters.keyword" clearable placeholder="名称、说明、组织或能源" /></el-form-item>
          <template #actions><el-button v-if="canConfigTemplate" :loading="templateLoading" @click="downloadTemplate">下载模板</el-button><el-button v-if="canConfigImport" @click="openImport">导入草稿</el-button><el-button v-if="canConfigExport" :loading="configExportLoading" @click="exportConfigs">导出当前筛选</el-button><el-button v-if="canConfigCreate" type="primary" @click="openCreateConfig">新增草稿</el-button></template>
        </ManagementToolbar>
        <el-alert v-if="energyTypesError" type="warning" :closable="false" show-icon :title="`能源类型字典读取失败：${energyTypesError}`" />
        <el-alert v-if="configError" type="error" :closable="false" show-icon :title="configError" />
        <section class="stat-grid" aria-label="预测配置草稿概览"><StatCard label="草稿总数" :value="formatInteger(configPagination.total)" note="当前筛选命中记录" /><StatCard label="草稿 / 启用" :value="`${configDraftCount} / ${configActiveCount}`" note="当前加载页状态分布" /><StatCard label="归档配置" :value="formatInteger(configArchivedCount)" note="归档保留追溯，不物理删除" /><StatCard label="已加载页数" :value="formatInteger(configs.length)" note="分页当前显示记录" /></section>
        <article class="page-card"><header class="table-heading"><span>共 {{ formatInteger(configPagination.total) }} 条</span><small>从草稿运行后，运行快照不随草稿后续编辑而改变。</small></header><PageState v-if="configError && !configs.length" :error="configError" @retry="loadConfigs" /><PageState v-else-if="!configs.length && !configLoading" description="暂无预测配置草稿；可新增或导入首条草稿。" /><template v-else><el-table :data="configs" v-loading="configLoading" stripe><el-table-column prop="name" label="配置名称" min-width="160" show-overflow-tooltip /><el-table-column prop="energyTypeName" label="能源类型" min-width="120" /><el-table-column prop="organizationScope" label="组织范围" min-width="130" show-overflow-tooltip /><el-table-column label="训练 / 目标月份" min-width="180"><template #default="{ row }">{{ row.trainStartMonth }} 至 {{ row.trainEndMonth }}<br>{{ row.predictStartMonth }} 至 {{ row.predictEndMonth }}</template></el-table-column><el-table-column label="算法" width="110"><template #default="{ row }">{{ algorithmLabel(row.algorithm) }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag size="small" :type="configStatusType(row.status)">{{ configStatusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="更新时间" min-width="160"><template #default="{ row }">{{ formatDateTime(row.updatedAt) }}</template></el-table-column><el-table-column label="操作" min-width="215" fixed="right"><template #default="{ row }"><el-button v-if="canConfigUpdate && row.status !== 'archived'" link type="primary" @click="openEditConfig(row)">编辑</el-button><el-button v-if="canConfigCreate" link @click="copyConfig(row)">复制</el-button><el-button v-if="canRunCreate && row.status !== 'archived'" link type="success" @click="confirmRunConfig(row)">从草稿运行</el-button><el-button v-if="canConfigStatus" link :type="row.status === 'archived' ? 'success' : 'warning'" @click="confirmConfigStatus(row)">{{ row.status === 'archived' ? '恢复草稿' : '归档' }}</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="configPage" v-model:page-size="configPageSize" layout="total, sizes, prev, pager, next" :page-sizes="[20, 50, 100]" :total="configPagination.total || 0" @current-change="loadConfigs" @size-change="changeConfigPageSize" /></div></template></article>
      </section>
      <PageState v-else description="当前账号没有 prediction:config:view 权限，配置草稿内容不可见。" />

      <section v-if="canRunView || canResultView" class="module-section">
        <header class="module-heading"><div class="heading-with-help"><h2>运行与只读结果</h2><HelpIcon label="查看运行与结果边界" content="运行记录及结果均来自服务端。仅 pending/running 状态可按服务端规则取消；完成、失败和已归档任务不可编辑或篡改结果。样本不足会真实显示失败原因，页面不会估算或补造结果。" /></div></header>
        <template v-if="canRunView">
          <ManagementToolbar :loading="runLoading" @search="applyRunFilters" @reset="resetRunFilters">
            <el-form-item label="状态"><el-select v-model="runDraftFilters.status" clearable placeholder="全部状态"><el-option v-for="item in runStatusOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item>
            <el-form-item label="算法"><el-select v-model="runDraftFilters.algorithm" clearable placeholder="全部算法"><el-option label="移动平均" value="moving_average" /><el-option label="线性趋势" value="linear_trend" /></el-select></el-form-item>
            <el-form-item label="能源类型"><el-select v-model="runDraftFilters.energyTypeCode" clearable placeholder="全部能源类型"><el-option v-for="item in energyTypes" :key="item.code" :label="`${item.name}（${item.code}）`" :value="item.code" /></el-select></el-form-item>
            <el-form-item label="目标月份"><el-date-picker v-model="runDraftFilters.targetMonth" type="month" value-format="YYYY-MM" placeholder="目标月份" /></el-form-item>
            <el-form-item label="字符搜索"><el-input v-model.trim="runDraftFilters.keyword" clearable placeholder="运行名称、说明或能源" /></el-form-item>
          </ManagementToolbar>
          <el-alert v-if="runError" type="error" :closable="false" show-icon :title="runError" />
          <section class="stat-grid" aria-label="真实预测运行统计"><StatCard label="运行总数" :value="formatInteger(runStats.totalRuns)" note="当前筛选下的服务端运行" /><StatCard label="完成 / 失败" :value="`${formatInteger(runStats.completedCount)} / ${formatInteger(runStats.failedCount)}`" note="样本不足不伪造结果" /><StatCard label="结果条数" :value="formatInteger(runStats.resultCount)" note="仅服务端生成结果" /><StatCard label="取消 / 归档" :value="`${formatInteger(runStats.cancelledCount)} / ${formatInteger(runStats.archivedCount)}`" note="终态记录保留追溯" /></section>
          <section class="chart-grid" aria-label="预测运行真实统计图表"><article v-for="chart in runCharts" :key="chart.key" class="page-card chart-panel"><header class="chart-heading"><div class="heading-with-help"><h3>{{ chart.title }}</h3><HelpIcon :label="`查看${chart.title}说明`" content="图表仅呈现当前筛选下服务端返回的真实预测运行和结果数量；状态与算法使用文本、图例及表格共同表达，不以颜色单独传递含义。" /></div></header><PageState v-if="runStatsError" :error="runStatsError" @retry="loadRuns" /><PageState v-else-if="!runChartRows(chart.key).length" description="当前筛选下暂无真实运行统计" /><template v-else><div class="bar-legend" :aria-label="`${chart.title}图例`"><span v-for="row in runChartRows(chart.key)" :key="runChartKey(chart.key, row)"><i :style="{ backgroundColor: predictionCategoryColor(runChartKey(chart.key, row)) }" />{{ runChartLabel(chart.key, row) }}</span></div><div class="bar-chart" @mouseleave="runChartTooltip = null"><button v-for="row in runChartRows(chart.key)" :key="runChartKey(chart.key, row)" class="bar-row" type="button" :aria-label="runChartTooltipLabel(chart.key, row)" @mouseenter="runChartTooltip = { key: chart.key, id: runChartKey(chart.key, row) }" @focus="runChartTooltip = { key: chart.key, id: runChartKey(chart.key, row) }"><span class="bar-name"><i :style="{ backgroundColor: predictionCategoryColor(runChartKey(chart.key, row)) }" />{{ runChartLabel(chart.key, row) }}</span><span class="bar-track"><span class="bar-fill" :style="{ width: `${percentage(row.runCount, runChartMax(chart.key))}%`, backgroundColor: predictionCategoryColor(runChartKey(chart.key, row)) }" /></span><span class="bar-value">{{ formatInteger(row.runCount) }} 次 / {{ formatInteger(row.resultCount) }} 条</span></button></div><p v-if="runChartTooltip?.key === chart.key" class="chart-tooltip" role="status">{{ runChartTooltipText(chart.key) }}</p><el-table :data="runChartRows(chart.key)" size="small" class="chart-table"><el-table-column :label="chart.columnLabel" min-width="130"><template #default="{ row }">{{ runChartLabel(chart.key, row) }}</template></el-table-column><el-table-column prop="runCount" label="运行次数" width="100" /><el-table-column prop="resultCount" label="结果条数" width="100" /></el-table></template></article></section>
          <article class="page-card"><header class="table-heading"><span>运行列表，共 {{ formatInteger(runPagination.total) }} 条</span><small>失败原因和服务端状态均保留原始运行说明。</small></header><PageState v-if="runError && !runs.length" :error="runError" @retry="loadRuns" /><PageState v-else-if="!runs.length && !runLoading" description="暂无预测运行；请先维护草稿并从草稿运行。" /><template v-else><el-table :data="runs" v-loading="runLoading" stripe><el-table-column prop="name" label="运行名称" min-width="150" show-overflow-tooltip /><el-table-column prop="energyTypeName" label="能源类型" min-width="115" /><el-table-column label="目标月份" min-width="145"><template #default="{ row }">{{ row.predictStartMonth }} 至 {{ row.predictEndMonth }}</template></el-table-column><el-table-column label="算法" width="105"><template #default="{ row }">{{ algorithmLabel(row.algorithm) }}</template></el-table-column><el-table-column label="结果" width="85"><template #default="{ row }">{{ formatInteger(row.resultCount) }} 条</template></el-table-column><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag size="small" :type="runStatusType(row.status)">{{ runStatusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="note" label="服务端说明 / 失败原因" min-width="230" show-overflow-tooltip /><el-table-column label="操作" min-width="145" fixed="right"><template #default="{ row }"><el-button v-if="canRunCancel && canCancelPredictionRun(row.status)" link type="danger" @click="confirmCancelRun(row)">取消</el-button><el-button v-if="canRunCancel && canArchivePredictionRun(row.status) && row.status !== 'archived'" link type="warning" @click="confirmArchiveRun(row)">归档</el-button><span v-if="!canCancelPredictionRun(row.status) && row.status !== 'archived'" class="readonly-text">结果只读</span></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="runPage" v-model:page-size="runPageSize" layout="total, sizes, prev, pager, next" :page-sizes="[20, 50, 100]" :total="runPagination.total || 0" @current-change="loadRuns" @size-change="changeRunPageSize" /></div></template></article>
        </template>
        <PageState v-else description="当前账号没有 prediction:run:view 权限，运行记录与统计不可见。" />

        <template v-if="canResultView">
          <ManagementToolbar :loading="resultLoading" @search="applyResultFilters" @reset="resetResultFilters"><el-form-item label="运行"><el-select v-model="resultDraftFilters.runId" clearable filterable placeholder="选择单次运行以查看趋势"><el-option v-for="row in runs" :key="row.id" :label="`${row.name}（#${row.id}）`" :value="row.id" /></el-select></el-form-item><el-form-item label="能源类型"><el-select v-model="resultDraftFilters.energyTypeCode" clearable placeholder="全部能源类型"><el-option v-for="item in energyTypes" :key="item.code" :label="`${item.name}（${item.code}）`" :value="item.code" /></el-select></el-form-item><el-form-item label="目标开始月份"><el-date-picker v-model="resultDraftFilters.targetMonthStart" type="month" value-format="YYYY-MM" /></el-form-item><el-form-item label="目标结束月份"><el-date-picker v-model="resultDraftFilters.targetMonthEnd" type="month" value-format="YYYY-MM" /></el-form-item><el-form-item label="运行状态"><el-select v-model="resultDraftFilters.runStatus" clearable placeholder="全部状态"><el-option v-for="item in runStatusOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="字符搜索"><el-input v-model.trim="resultDraftFilters.keyword" clearable placeholder="运行、能源或方法说明" /></el-form-item><template #actions><el-button v-if="canResultExport" :loading="resultExportLoading" @click="exportResults">导出当前筛选</el-button></template></ManagementToolbar>
          <el-alert v-if="resultError" type="error" :closable="false" show-icon :title="resultError" />
          <article class="page-card chart-panel"><header class="chart-heading"><div class="heading-with-help"><h3>实际预测结果趋势</h3><HelpIcon label="查看结果趋势口径" content="仅在选择单次服务端运行后显示；结果按预测单位分面，不跨单位相加。柱形长度共用一个数值轴，图例、悬停提示与下方表格共同表达实体和数值。" /></div><el-select v-model="selectedResultUnit" size="small" class="unit-select" placeholder="选择预测单位"><el-option v-for="unit in resultUnits" :key="unit" :label="unit" :value="unit" /></el-select></header><PageState v-if="!resultAppliedFilters.runId" description="请选择单次运行后查看其服务端实际预测结果趋势。" /><PageState v-else-if="resultTrendError" :error="resultTrendError" @retry="loadResults" /><PageState v-else-if="!resultTrendRows.length" description="当前运行和筛选下暂无服务端预测结果；若任务失败，请在运行列表查看真实失败原因。" /><template v-else><div class="bar-legend" aria-label="预测结果能源类型图例"><span v-for="row in resultTrendRows" :key="`${row.energyTypeCode}-${row.targetMonth}`"><i :style="{ backgroundColor: predictionCategoryColor(row.energyTypeCode) }" />{{ row.energyTypeName }}</span></div><div class="bar-chart" @mouseleave="resultTooltip = null"><button v-for="row in resultTrendRows" :key="`${row.energyTypeCode}-${row.targetMonth}`" class="bar-row" type="button" :aria-label="resultTooltipLabel(row)" @mouseenter="resultTooltip = row" @focus="resultTooltip = row"><span class="bar-name"><i :style="{ backgroundColor: predictionCategoryColor(row.energyTypeCode) }" />{{ row.targetMonth }} · {{ row.energyTypeName }}</span><span class="bar-track"><span class="bar-fill" :style="{ width: `${percentage(row.predictedValue, resultTrendMax)}%`, backgroundColor: predictionCategoryColor(row.energyTypeCode) }" /></span><span class="bar-value">{{ formatNumber(row.predictedValue) }} {{ row.predictedUnit }}</span></button></div><p v-if="resultTooltip" class="chart-tooltip" role="status">{{ resultTooltipLabel(resultTooltip) }}</p><el-table :data="resultTrendRows" size="small" class="chart-table"><el-table-column prop="targetMonth" label="目标月份" width="105" /><el-table-column prop="energyTypeName" label="能源类型" min-width="120" /><el-table-column label="预测值" min-width="140"><template #default="{ row }">{{ formatNumber(row.predictedValue) }} {{ row.predictedUnit }}</template></el-table-column><el-table-column prop="resultCount" label="结果数" width="90" /></el-table></template></article>
          <article class="page-card"><header class="table-heading"><div class="heading-with-help"><h3>只读预测结果列表</h3><HelpIcon label="查看预测结果只读说明" content="列表只读取服务端基于 active 能耗数据生成的 prediction_results。页面没有人工导入、新增、编辑、删除或覆盖入口；导出也仅导出当前服务端筛选结果。" /></div><span>共 {{ formatInteger(resultPagination.total) }} 条</span></header><PageState v-if="resultError && !results.length" :error="resultError" @retry="loadResults" /><PageState v-else-if="!results.length && !resultLoading" description="暂无服务端预测结果。" /><template v-else><el-table :data="results" v-loading="resultLoading" stripe><el-table-column prop="predictionRunName" label="运行" min-width="150" show-overflow-tooltip /><el-table-column prop="energyTypeName" label="能源类型" min-width="115" /><el-table-column prop="targetMonth" label="目标月份" width="105" /><el-table-column label="预测值" min-width="130"><template #default="{ row }">{{ formatNumber(row.predictedValue) }} {{ row.predictedUnit }}</template></el-table-column><el-table-column label="置信范围" min-width="155"><template #default="{ row }">{{ formatNumber(row.confidenceLow) }} 至 {{ formatNumber(row.confidenceHigh) }}</template></el-table-column><el-table-column label="运行状态" width="100"><template #default="{ row }"><el-tag size="small" :type="runStatusType(row.runStatus)">{{ runStatusLabel(row.runStatus) }}</el-tag></template></el-table-column><el-table-column prop="methodNote" label="服务端方法说明" min-width="220" show-overflow-tooltip /></el-table><div class="pagination"><el-pagination v-model:current-page="resultPage" v-model:page-size="resultPageSize" layout="total, sizes, prev, pager, next" :page-sizes="[20, 50, 100]" :total="resultPagination.total || 0" @current-change="loadResults" @size-change="changeResultPageSize" /></div></template></article>
        </template>
        <PageState v-else description="当前账号没有 prediction:result:view 权限，预测结果内容不可见。" />
      </section>

      <ManagementDrawer v-model="configDrawerOpen" :title="configEditingId ? '编辑预测配置草稿' : '新增预测配置草稿'" :loading="configSaving" :confirm-disabled="configFormBlocked" @save="saveConfig"><el-alert v-if="configFormError" type="error" :closable="false" show-icon :title="configFormError" class="drawer-alert" /><el-alert v-if="!activeEnergyTypes.length" type="warning" :closable="false" show-icon title="暂无可选 active 能源类型，请先维护能源类型后再保存草稿。" class="drawer-alert" /><el-form ref="configFormRef" :model="configForm" :rules="configRules" label-position="top"><el-form-item label="配置名称" prop="name"><HelpIcon label="查看配置名称说明" content="名称用于草稿识别和导入去重；同名导入会按 skip 策略保留 warning，不覆盖已有草稿。" /><el-input v-model.trim="configForm.name" maxlength="200" show-word-limit /></el-form-item><el-form-item label="能源类型" prop="energyTypeCode"><HelpIcon label="查看能源类型说明" content="只能选择 active 能源类型，服务端会使用其对应的已入库 active 能耗记录训练。" /><el-select v-model="configForm.energyTypeCode" class="drawer-control" placeholder="选择 active 能源类型"><el-option v-for="item in activeEnergyTypes" :key="item.code" :label="`${item.name}（${item.code}）`" :value="item.code" /></el-select></el-form-item><el-form-item label="组织范围"><HelpIcon label="查看组织范围说明" content="填写时按精确组织名称筛选训练能耗；留空表示不以组织限制历史数据。" /><el-input v-model.trim="configForm.organizationScope" maxlength="255" /></el-form-item><el-form-item label="站点"><el-input v-model.trim="configForm.site" maxlength="255" /></el-form-item><el-form-item label="部门"><el-input v-model.trim="configForm.department" maxlength="255" /></el-form-item><el-form-item label="训练月份" required><div class="month-row"><el-form-item prop="trainStartMonth"><el-date-picker v-model="configForm.trainStartMonth" type="month" value-format="YYYY-MM" placeholder="开始月份" /></el-form-item><span>至</span><el-form-item prop="trainEndMonth"><el-date-picker v-model="configForm.trainEndMonth" type="month" value-format="YYYY-MM" placeholder="结束月份" /></el-form-item></div></el-form-item><el-form-item label="预测目标月份" required><div class="month-row"><el-form-item prop="predictStartMonth"><el-date-picker v-model="configForm.predictStartMonth" type="month" value-format="YYYY-MM" placeholder="开始月份" /></el-form-item><span>至</span><el-form-item prop="predictEndMonth"><el-date-picker v-model="configForm.predictEndMonth" type="month" value-format="YYYY-MM" placeholder="结束月份" /></el-form-item></div></el-form-item><el-form-item label="算法" prop="algorithm"><HelpIcon label="查看算法说明" content="移动平均需要足够连续历史月份；样本不足时服务端会创建 failed 运行并保留真实原因，不会虚构预测结果。" /><el-select v-model="configForm.algorithm"><el-option label="移动平均" value="moving_average" /><el-option label="线性趋势" value="linear_trend" /></el-select></el-form-item><el-form-item v-if="configForm.algorithm === 'moving_average'" label="移动平均窗口"><el-input-number v-model="configForm.windowSize" :min="2" :max="12" /></el-form-item><el-form-item label="状态"><el-select v-model="configForm.status"><el-option label="草稿" value="draft" /><el-option label="启用" value="active" /></el-select></el-form-item><el-form-item label="说明"><el-input v-model.trim="configForm.note" type="textarea" :rows="3" maxlength="1000" show-word-limit /></el-form-item></el-form></ManagementDrawer>
      <ManagementDrawer v-model="importDrawerOpen" title="导入预测配置草稿：上传预演" confirm-label="开始预演" :loading="previewLoading" :confirm-disabled="!importFile" @save="previewImport"><p class="drawer-notice">预演仅校验并保存导入审计，不写配置、运行或结果。导入执行只生成 draft 草稿；预测结果必须由服务端依据已入库能耗数据在“从草稿运行”时生成。</p><el-upload :auto-upload="false" :limit="1" accept=".xlsx,.xls,.csv" :on-change="selectImportFile" :on-remove="clearImportFile"><el-button>选择预测配置表格</el-button><template #tip><div class="el-upload__tip">支持 .xlsx、.xls、.csv；请先下载模板核对字段。</div></template></el-upload><el-alert v-if="importError" type="error" :closable="false" show-icon :title="importError" class="drawer-alert" /><template v-if="importPreview"><div class="preview-summary"><span>候选 {{ formatInteger(importPreview.summary?.wouldImport) }}</span><span>跳过 {{ formatInteger(importPreview.summary?.skipped) }}</span><span>阻断 {{ formatInteger(importPreview.summary?.blocked) }}</span><span>warning {{ formatInteger(importPreview.summary?.warnings) }}</span></div><el-table :data="importPreview.items || []" size="small" max-height="240"><el-table-column prop="rowNumber" label="行" width="60" /><el-table-column prop="status" label="结果" width="95" /><el-table-column prop="name" label="配置名称" min-width="130" /><el-table-column prop="reasonText" label="行错误 / warning" min-width="220" show-overflow-tooltip /></el-table><el-button class="execute-import-button" type="danger" :disabled="!canExecuteImport" @click="openExecuteImport">进入执行确认</el-button></template></ManagementDrawer>
      <ManagementDrawer v-model="executeDrawerOpen" title="确认执行预测配置草稿导入" confirm-label="确认导入" :loading="executeLoading" :confirm-disabled="confirmText !== importPreview?.confirmText || !canExecuteImport" @save="executeImport"><p class="drawer-notice">执行只会按当前预演签名候选创建 draft 配置，并由后端创建备份；不会运行预测，不会写预测结果、能耗或碳排放。</p><el-form label-position="top"><el-form-item :label="`请输入固定确认文本：${importPreview?.confirmText || ''}`"><el-input v-model="confirmText" /></el-form-item></el-form><el-alert v-if="executeError" type="error" :closable="false" show-icon :title="executeError" /></ManagementDrawer>
    </template>
  </ManagementPage>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import ManagementPage from '@/components/ManagementPage.vue';
import ManagementToolbar from '@/components/ManagementToolbar.vue';
import ManagementDrawer from '@/components/ManagementDrawer.vue';
import HelpIcon from '@/components/HelpIcon.vue';
import PageState from '@/components/PageState.vue';
import StatCard from '@/components/StatCard.vue';
import { getEnergyTypes } from '@/api/energy';
import { archivePredictionRun, cancelPredictionRun, copyPredictionConfig, createPredictionConfig, downloadPredictionConfigTemplate, executePredictionConfigImport, exportPredictionConfigs, exportPredictionResults, getPredictionConfig, getPredictionConfigs, getPredictionResults, getPredictionRunResults, getPredictionRunStats, getPredictionRuns, previewPredictionConfigImport, runPredictionConfig, updatePredictionConfig, updatePredictionConfigStatus } from '@/api/predictions';
import { buildPredictionConfigFilters, buildPredictionConfigImportExecutePayload, buildPredictionResultFilters, buildPredictionRunFilters, buildPredictionTrendRows, canArchivePredictionRun, canCancelPredictionRun, nextPredictionConfigStatus, numberValue, predictionCategoryColor } from '@/utils/predictionManagement';
import { hasPermi } from '@/utils/permission';

/** 返回空预测配置筛选。 */
const emptyConfigFilters = () => ({ status: '', energyTypeCode: '', algorithm: '', keyword: '' });
/** 返回空预测运行筛选。 */
const emptyRunFilters = () => ({ status: '', algorithm: '', energyTypeCode: '', targetMonth: '', keyword: '' });
/** 返回空预测结果筛选。 */
const emptyResultFilters = () => ({ runId: '', energyTypeCode: '', targetMonthStart: '', targetMonthEnd: '', runStatus: '', keyword: '' });
/** 返回新增预测草稿默认表单。 */
const emptyConfigForm = () => ({ name: '', note: '', energyTypeCode: '', organizationScope: '', site: '', department: '', trainStartMonth: '', trainEndMonth: '', predictStartMonth: '', predictEndMonth: '', algorithm: 'moving_average', windowSize: 3, status: 'draft' });
/** 捕获 API 错误供对应页面区域真实展示。 */
const safe = async (task) => { try { return { ok: true, value: await task() }; } catch (error) { return { ok: false, error }; } };
/** 提取服务端可读错误消息。 */
const requestError = (result) => result?.error?.message || '接口请求失败。';
/** 真实运行统计图的固定维度定义。 */
const runCharts = Object.freeze([{ key: 'status', title: '运行状态结构', columnLabel: '状态' }, { key: 'algorithm', title: '算法结构', columnLabel: '算法' }]);
/** 运行状态选项。 */
const runStatusOptions = Object.freeze([{ value: 'pending', label: '待运行' }, { value: 'running', label: '运行中' }, { value: 'completed', label: '已完成' }, { value: 'failed', label: '失败' }, { value: 'cancelled', label: '已取消' }, { value: 'archived', label: '已归档' }]);

// 权限仅控制前端可见性，服务端 prediction:* 权限仍是最终边界。
const canConfigView = computed(() => hasPermi('prediction:config:view'));
const canConfigCreate = computed(() => hasPermi('prediction:config:create'));
const canConfigUpdate = computed(() => hasPermi('prediction:config:update'));
const canConfigStatus = computed(() => hasPermi('prediction:config:status'));
const canConfigImport = computed(() => hasPermi('prediction:config:import'));
const canConfigExport = computed(() => hasPermi('prediction:config:export'));
const canConfigTemplate = computed(() => hasPermi('prediction:config:template'));
const canRunCreate = computed(() => hasPermi('prediction:run:create'));
const canRunView = computed(() => hasPermi('prediction:run:view'));
const canRunCancel = computed(() => hasPermi('prediction:run:cancel'));
const canResultView = computed(() => hasPermi('prediction:result:view'));
const canResultExport = computed(() => hasPermi('prediction:result:export'));
const canManagePredictions = computed(() => hasPermi(['prediction:config:view', 'prediction:run:view', 'prediction:result:view']));

// 配置草稿、字典和导入抽屉状态。
const energyTypes = ref([]); const energyTypesError = ref('');
const configDraftFilters = ref(emptyConfigFilters()); const configAppliedFilters = ref(emptyConfigFilters()); const configs = ref([]); const configPage = ref(1); const configPageSize = ref(20); const configPagination = ref({ total: 0 }); const configLoading = ref(false); const configError = ref(''); const configExportLoading = ref(false); const templateLoading = ref(false);
const configDrawerOpen = ref(false); const configEditingId = ref(null); const configForm = ref(emptyConfigForm()); const configFormRef = ref(); const configSaving = ref(false); const configFormError = ref('');
const importDrawerOpen = ref(false); const executeDrawerOpen = ref(false); const importFile = ref(null); const importPreview = ref(null); const previewLoading = ref(false); const executeLoading = ref(false); const importError = ref(''); const executeError = ref(''); const confirmText = ref('');
const configRules = { name: [{ required: true, message: '请填写配置名称。', trigger: 'blur' }], energyTypeCode: [{ required: true, message: '请选择 active 能源类型。', trigger: 'change' }], trainStartMonth: [{ required: true, message: '请选择训练开始月份。', trigger: 'change' }], trainEndMonth: [{ required: true, message: '请选择训练结束月份。', trigger: 'change' }], predictStartMonth: [{ required: true, message: '请选择目标开始月份。', trigger: 'change' }], predictEndMonth: [{ required: true, message: '请选择目标结束月份。', trigger: 'change' }], algorithm: [{ required: true, message: '请选择预测算法。', trigger: 'change' }] };

// 运行、真实统计和只读结果状态。
const runDraftFilters = ref(emptyRunFilters()); const runAppliedFilters = ref(emptyRunFilters()); const runs = ref([]); const runPage = ref(1); const runPageSize = ref(20); const runPagination = ref({ total: 0 }); const runLoading = ref(false); const runError = ref(''); const runStatsError = ref(''); const runStats = ref({ totalRuns: 0, completedCount: 0, failedCount: 0, cancelledCount: 0, archivedCount: 0, resultCount: 0, byStatus: [], byAlgorithm: [] }); const runChartTooltip = ref(null);
const resultDraftFilters = ref(emptyResultFilters()); const resultAppliedFilters = ref(emptyResultFilters()); const results = ref([]); const trendResults = ref([]); const resultPage = ref(1); const resultPageSize = ref(20); const resultPagination = ref({ total: 0 }); const resultLoading = ref(false); const resultError = ref(''); const resultTrendError = ref(''); const resultExportLoading = ref(false); const selectedResultUnit = ref(''); const resultTooltip = ref(null);

/** 返回 active 能源类型，避免选择停用能源。 */
const activeEnergyTypes = computed(() => energyTypes.value.filter((item) => Number(item.isActive) === 1 || item.isActive === true));
/** 草稿抽屉只有依赖字典就绪且未保存时才可提交。 */
const configFormBlocked = computed(() => configSaving.value || !activeEnergyTypes.value.length);
/** 只接受服务端签名的完整 preview 候选，才可进入 execute。 */
const canExecuteImport = computed(() => Boolean(importPreview.value?.batchId && importPreview.value?.previewSignature && numberValue(importPreview.value?.summary?.wouldImport) > 0 && Array.isArray(importPreview.value?.candidateRows) && importPreview.value.candidateRows.length === numberValue(importPreview.value.summary?.wouldImport)));
/** 当前页配置状态数量。 */
const configDraftCount = computed(() => formatInteger(configs.value.filter((row) => row.status === 'draft').length));
/** 当前页启用配置数量。 */
const configActiveCount = computed(() => formatInteger(configs.value.filter((row) => row.status === 'active').length));
/** 当前页已归档配置数量。 */
const configArchivedCount = computed(() => formatInteger(configs.value.filter((row) => row.status === 'archived').length));
/** 单次运行中存在的预测单位，趋势必须选定其一。 */
const resultUnits = computed(() => [...new Set(trendResults.value.map((row) => row.predictedUnit).filter(Boolean))]);
/** 只读取一个运行且同一预测单位的真实结果趋势。 */
const resultTrendRows = computed(() => resultAppliedFilters.value.runId ? buildPredictionTrendRows(trendResults.value, selectedResultUnit.value) : []);
/** 结果趋势单轴的最大实际预测值。 */
const resultTrendMax = computed(() => Math.max(...resultTrendRows.value.map((row) => numberValue(row.predictedValue)), 1));

/** 格式化业务数值。 */
function formatNumber(value, digits = 2) { return new Intl.NumberFormat('zh-CN', { maximumFractionDigits: digits }).format(numberValue(value)); }
/** 格式化整数。 */
function formatInteger(value) { return formatNumber(value, 0); }
/** 格式化服务端日期时间。 */
function formatDateTime(value) { return value ? String(value).replace('T', ' ').replace(/\.\d+Z$/, '') : '—'; }
/** 计算单轴柱状图安全长度。 */
function percentage(value, maximum) { return Math.max(2, Math.min(100, (numberValue(value) / maximum) * 100)); }
/** 返回算法可读标签。 */
function algorithmLabel(value) { return ({ moving_average: '移动平均', linear_trend: '线性趋势' })[value] || value || '—'; }
/** 返回配置状态标签。 */
function configStatusLabel(value) { return ({ draft: '草稿', active: '启用', archived: '已归档' })[value] || value || '未知'; }
/** 返回配置状态 Element 标签类型。 */
function configStatusType(value) { return ({ draft: 'info', active: 'success', archived: 'warning' })[value] || 'info'; }
/** 返回运行状态标签。 */
function runStatusLabel(value) { return ({ pending: '待运行', running: '运行中', completed: '已完成', failed: '失败', cancelled: '已取消', archived: '已归档' })[value] || value || '未知'; }
/** 返回运行状态 Element 标签类型，状态文本始终一起展示。 */
function runStatusType(value) { return ({ pending: 'info', running: 'primary', completed: 'success', failed: 'danger', cancelled: 'warning', archived: 'info' })[value] || 'info'; }
/** 返回服务端真实运行统计维度行。 */
function runChartRows(key) { return key === 'status' ? runStats.value.byStatus || [] : runStats.value.byAlgorithm || []; }
/** 返回固定实体键，状态与算法不会因排序改色。 */
function runChartKey(key, row) { return `${key}:${key === 'status' ? row.status : row.algorithm}`; }
/** 返回统计行可读标签。 */
function runChartLabel(key, row) { return key === 'status' ? runStatusLabel(row.status) : algorithmLabel(row.algorithm); }
/** 返回统计图单轴最大运行次数。 */
function runChartMax(key) { return Math.max(...runChartRows(key).map((row) => numberValue(row.runCount)), 1); }
/** 返回悬停统计提示。 */
function runChartTooltipLabel(key, row) { return `${runChartLabel(key, row)}：真实运行 ${formatInteger(row.runCount)} 次，服务端结果 ${formatInteger(row.resultCount)} 条。`; }
/** 返回当前运行统计提示文本。 */
function runChartTooltipText(key) { const row = runChartRows(key).find((item) => runChartKey(key, item) === runChartTooltip.value?.id); return row ? runChartTooltipLabel(key, row) : ''; }
/** 返回结果趋势悬停提示。 */
function resultTooltipLabel(row) { return `${row.targetMonth} ${row.energyTypeName}：服务端预测 ${formatNumber(row.predictedValue)} ${row.predictedUnit}，来自 ${formatInteger(row.resultCount)} 条结果。`; }

/** 加载能源类型字典。 */
async function loadEnergyTypes() { const result = await safe(getEnergyTypes); if (result.ok) { energyTypes.value = result.value.data || []; energyTypesError.value = ''; } else energyTypesError.value = requestError(result); }
/** 加载当前应用筛选的配置列表。 */
async function loadConfigs() { if (!canConfigView.value) return; configLoading.value = true; const result = await safe(() => getPredictionConfigs(buildPredictionConfigFilters(configAppliedFilters.value, { page: configPage.value, pageSize: configPageSize.value }))); configLoading.value = false; if (result.ok) { configs.value = result.value.data || []; configPagination.value = result.value.meta?.pagination || {}; configError.value = ''; } else { configs.value = []; configError.value = requestError(result); } }
/** 并行读取运行列表和真实统计，错误按区域展示。 */
async function loadRuns() { if (!canRunView.value) return; runLoading.value = true; const filters = buildPredictionRunFilters(runAppliedFilters.value, { page: runPage.value, pageSize: runPageSize.value }); const [listResult, statsResult] = await Promise.all([safe(() => getPredictionRuns(filters)), safe(() => getPredictionRunStats(buildPredictionRunFilters(runAppliedFilters.value)))]); runLoading.value = false; if (listResult.ok) { runs.value = listResult.value.data || []; runPagination.value = listResult.value.meta?.pagination || {}; runError.value = ''; } else { runs.value = []; runError.value = requestError(listResult); } if (statsResult.ok) { runStats.value = statsResult.value.data || { byStatus: [], byAlgorithm: [] }; runStatsError.value = ''; } else { runStatsError.value = requestError(statsResult); } }
/** 加载服务端只读结果，趋势仅在选择单次运行后显示。 */
async function loadResults() { if (!canResultView.value) return; resultLoading.value = true; const filters = buildPredictionResultFilters(resultAppliedFilters.value, { page: resultPage.value, pageSize: resultPageSize.value }); const trendFilters = buildPredictionResultFilters(resultAppliedFilters.value, { page: 1, pageSize: 500 }); const [listResult, trendResult] = await Promise.all([safe(() => getPredictionResults(filters)), resultAppliedFilters.value.runId ? safe(() => getPredictionRunResults(resultAppliedFilters.value.runId, trendFilters)) : Promise.resolve({ ok: true, value: { data: [] } })]); resultLoading.value = false; if (listResult.ok) { results.value = listResult.value.data || []; resultPagination.value = listResult.value.meta?.pagination || {}; resultError.value = ''; } else { results.value = []; resultError.value = requestError(listResult); } if (trendResult.ok) { trendResults.value = trendResult.value.data || []; resultTrendError.value = ''; if (!resultUnits.value.includes(selectedResultUnit.value)) selectedResultUnit.value = resultUnits.value[0] || ''; } else { trendResults.value = []; resultTrendError.value = requestError(trendResult); } }

/** 应用配置草稿筛选。 */
function applyConfigFilters() { configAppliedFilters.value = { ...configDraftFilters.value }; configPage.value = 1; loadConfigs(); }
/** 重置配置草稿筛选。 */
function resetConfigFilters() { configDraftFilters.value = emptyConfigFilters(); configAppliedFilters.value = emptyConfigFilters(); configPage.value = 1; loadConfigs(); }
/** 配置页大小变更时回到第一页。 */
function changeConfigPageSize() { configPage.value = 1; loadConfigs(); }
/** 应用运行筛选。 */
function applyRunFilters() { runAppliedFilters.value = { ...runDraftFilters.value }; runPage.value = 1; loadRuns(); }
/** 重置运行筛选。 */
function resetRunFilters() { runDraftFilters.value = emptyRunFilters(); runAppliedFilters.value = emptyRunFilters(); runPage.value = 1; loadRuns(); }
/** 运行页大小变更时回到第一页。 */
function changeRunPageSize() { runPage.value = 1; loadRuns(); }
/** 应用只读结果筛选。 */
function applyResultFilters() { resultAppliedFilters.value = { ...resultDraftFilters.value }; resultPage.value = 1; loadResults(); }
/** 重置只读结果筛选。 */
function resetResultFilters() { resultDraftFilters.value = emptyResultFilters(); resultAppliedFilters.value = emptyResultFilters(); resultPage.value = 1; loadResults(); }
/** 结果页大小变更时回到第一页。 */
function changeResultPageSize() { resultPage.value = 1; loadResults(); }

/** 打开新增草稿抽屉。 */
function openCreateConfig() { configEditingId.value = null; configForm.value = emptyConfigForm(); configFormError.value = ''; configDrawerOpen.value = true; }
/** 读取服务端详情后打开编辑抽屉。 */
async function openEditConfig(row) { configFormError.value = ''; const result = await safe(() => getPredictionConfig(row.id)); if (!result.ok) { ElMessage.error(`读取预测配置详情失败：${requestError(result)}`); return; } const config = result.value.data || {}; configEditingId.value = config.id; configForm.value = { name: config.name || '', note: config.note || '', energyTypeCode: config.energyTypeCode || '', organizationScope: config.organizationScope || '', site: config.site || '', department: config.department || '', trainStartMonth: config.trainStartMonth || '', trainEndMonth: config.trainEndMonth || '', predictStartMonth: config.predictStartMonth || '', predictEndMonth: config.predictEndMonth || '', algorithm: config.algorithm || 'moving_average', windowSize: config.windowSize || 3, status: config.status === 'active' ? 'active' : 'draft' }; configDrawerOpen.value = true; }
/** 保存草稿，结果不会由页面写入。 */
async function saveConfig() { if (configFormBlocked.value) return; const valid = await configFormRef.value?.validate().catch(() => false); if (!valid) return; configSaving.value = true; configFormError.value = ''; const result = await safe(() => configEditingId.value ? updatePredictionConfig(configEditingId.value, { ...configForm.value }) : createPredictionConfig({ ...configForm.value })); configSaving.value = false; if (!result.ok) { configFormError.value = requestError(result); return; } configDrawerOpen.value = false; ElMessage.success(configEditingId.value ? '预测配置草稿已更新。' : '预测配置草稿已新增。'); await loadConfigs(); }
/** 二次确认后归档或恢复配置，不进行物理删除。 */
async function confirmConfigStatus(row) { const status = nextPredictionConfigStatus(row.status); const action = status === 'archived' ? '归档' : '恢复草稿'; try { await ElMessageBox.confirm(`${action}“${row.name}”？${status === 'archived' ? '归档不是物理删除，配置及历史运行保持追溯；归档草稿不可编辑或运行。' : '恢复后将成为可编辑草稿。'}`, `确认${action}`, { type: status === 'archived' ? 'warning' : 'info', confirmButtonText: `确认${action}`, cancelButtonText: '取消' }); } catch { return; } const result = await safe(() => updatePredictionConfigStatus(row.id, status)); if (!result.ok) { ElMessage.error(`预测配置${action}失败：${requestError(result)}`); return; } ElMessage.success(`预测配置已${action}。`); await loadConfigs(); }
/** 复制配置为新的可编辑 draft。 */
async function copyConfig(row) { const result = await safe(() => copyPredictionConfig(row.id)); if (!result.ok) { ElMessage.error(`复制预测配置失败：${requestError(result)}`); return; } ElMessage.success('已复制为新的预测配置草稿。'); await loadConfigs(); }
/** 从草稿触发服务端运行并刷新运行及结果。 */
async function confirmRunConfig(row) { try { await ElMessageBox.confirm(`从草稿“${row.name}”创建预测运行？服务端将读取已入库 active 能耗数据并保存不可变配置快照；样本不足将真实失败且不写结果。`, '确认从草稿运行', { type: 'warning', confirmButtonText: '创建运行', cancelButtonText: '取消' }); } catch { return; } const result = await safe(() => runPredictionConfig(row.id)); if (!result.ok) { ElMessage.error(`创建预测运行失败：${requestError(result)}`); return; } const summary = result.value.data?.summary || {}; ElMessage.success(`服务端运行已结束：${summary.status === 'failed' ? '样本不足或无数据，未生成结果' : `生成 ${formatInteger(summary.resultCount)} 条结果`}。`); await Promise.all([loadRuns(), loadResults()]); }
/** 下载服务端权限保护的配置模板。 */
async function downloadTemplate() { templateLoading.value = true; const result = await safe(() => downloadPredictionConfigTemplate()); templateLoading.value = false; if (!result.ok) ElMessage.error(`预测配置模板下载失败：${requestError(result)}`); }
/** 导出当前应用的配置筛选，而非尚未查询的草稿筛选。 */
async function exportConfigs() { configExportLoading.value = true; const result = await safe(() => exportPredictionConfigs(buildPredictionConfigFilters(configAppliedFilters.value))); configExportLoading.value = false; if (!result.ok) ElMessage.error(`预测配置导出失败：${requestError(result)}`); }

/** 初始化配置草稿导入状态。 */
function openImport() { importDrawerOpen.value = true; importFile.value = null; importPreview.value = null; importError.value = ''; executeError.value = ''; confirmText.value = ''; }
/** 记录当前可信本地上传文件并清除旧预演。 */
function selectImportFile(file) { importFile.value = file.raw || null; importPreview.value = null; importError.value = ''; }
/** 清除上传文件和旧预演，避免误用候选。 */
function clearImportFile() { importFile.value = null; importPreview.value = null; }
/** 上传文件创建服务端只读预演。 */
async function previewImport() { if (!importFile.value) return; previewLoading.value = true; importError.value = ''; const result = await safe(() => previewPredictionConfigImport(importFile.value)); previewLoading.value = false; if (!result.ok) { importPreview.value = null; importError.value = `预测配置导入预演失败：${requestError(result)}`; return; } importPreview.value = result.value.data || {}; ElMessage.success('预测配置草稿预演已完成，请核对候选、跳过和阻断行。'); }
/** 打开带固定确认文本的导入执行抽屉。 */
function openExecuteImport() { executeError.value = ''; confirmText.value = ''; executeDrawerOpen.value = true; }
/** 原样提交服务端签名的候选，execute 只创建 draft。 */
async function executeImport() { if (!canExecuteImport.value || confirmText.value !== importPreview.value?.confirmText) return; executeLoading.value = true; executeError.value = ''; const result = await safe(() => executePredictionConfigImport({ ...buildPredictionConfigImportExecutePayload(importPreview.value), confirmText: confirmText.value })); executeLoading.value = false; if (!result.ok) { executeError.value = `预测配置草稿导入失败：${requestError(result)}`; return; } executeDrawerOpen.value = false; importDrawerOpen.value = false; importPreview.value = null; ElMessage.success(`预测配置草稿导入完成：成功 ${formatInteger(result.value.data?.imported)} 条；未运行预测，未写入结果。`); await loadConfigs(); }

/** 取消仅调用服务端允许的 pending/running 运行。 */
async function confirmCancelRun(row) { try { await ElMessageBox.confirm(`取消运行“${row.name}”？仅服务端仍处于 pending/running 的任务允许取消；已完成、失败结果不会被改写。`, '确认取消', { type: 'warning', confirmButtonText: '确认取消', cancelButtonText: '返回' }); } catch { return; } const result = await safe(() => cancelPredictionRun(row.id)); if (!result.ok) { ElMessage.error(`取消预测运行失败：${requestError(result)}`); return; } ElMessage.success('预测运行已取消，已有结果保持只读。'); await Promise.all([loadRuns(), loadResults()]); }
/** 归档服务端终态运行，结果保持只读。 */
async function confirmArchiveRun(row) { try { await ElMessageBox.confirm(`归档终态运行“${row.name}”？归档不是删除，服务端预测结果仍保持只读可追溯。`, '确认归档', { type: 'warning', confirmButtonText: '确认归档', cancelButtonText: '取消' }); } catch { return; } const result = await safe(() => archivePredictionRun(row.id)); if (!result.ok) { ElMessage.error(`归档预测运行失败：${requestError(result)}`); return; } ElMessage.success('预测运行已归档，结果保持只读。'); await Promise.all([loadRuns(), loadResults()]); }
/** 导出当前应用的服务端结果筛选。 */
async function exportResults() { resultExportLoading.value = true; const result = await safe(() => exportPredictionResults(buildPredictionResultFilters(resultAppliedFilters.value))); resultExportLoading.value = false; if (!result.ok) ElMessage.error(`预测结果导出失败：${requestError(result)}`); }

/** 页面加载时仅读取当前账号有权限查看的资源。 */
onMounted(async () => { if (!canManagePredictions.value) return; await loadEnergyTypes(); await Promise.all([loadConfigs(), loadRuns(), loadResults()]); });
</script>

