;line-height:1.7}.drawer-control{width:100%}.preview-summary{display:flex;flex-wrap:wrap;gap:14px;margin:16px 0;color:#516170;font-size:13px}.execute-import-button{margin-top:14px}.month-row{display:flex;align-items:center;gap:8px}.month-row .el-form-item{margin-bottom:0}.readonly-text{color:#7385a2;font-size:12px}@media (max-width:1120px){.chart-grid{grid-template-columns:1fr}.chart-panel{overflow-x:auto}}@media (max-width:900px){.stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media (max-width:640px){.stat-grid{grid-template-columns:1fr}.module-heading,.chart-heading{align-items:flex-start;flex-direction:column}.bar-row{grid-template-columns:1fr}.bar-value{text-align:left}.month-row{align-items:stretch;flex-direction:column}}
